import torch
from .quant import dequantize as gq
from .reader import GGMLQuantizationType, GGML_QUANT_SIZES
from tqdm import tqdm
TORCH_COMPATIBLE_QTYPES = {None, GGMLQuantizationType.F32,
    GGMLQuantizationType.F16}
def is_torch_compatible(tensor):
    return tensor is None or getattr(tensor, 'tensor_type', None
        ) in TORCH_COMPATIBLE_QTYPES
def is_quantized(tensor):
    return not is_torch_compatible(tensor)
def dequantize(data, qtype, oshape, dtype=None):
    block_size, type_size = GGML_QUANT_SIZES[qtype]
    dequantize_blocks = dequantize_functions[qtype]
    rows = data.reshape((-1, data.shape[-1])).view(torch.uint8)
    n_blocks = rows.numel() // type_size
    blocks = rows.reshape((n_blocks, type_size))
    blocks = dequantize_blocks(blocks, block_size, type_size, dtype)
    return blocks.reshape(oshape)
def dequantize_tensor(tensor, dtype=None, dequant_dtype=None):
    qtype = getattr(tensor, 'tensor_type', None)
    oshape = getattr(tensor, 'tensor_shape', tensor.shape)
    if qtype in TORCH_COMPATIBLE_QTYPES:
        return tensor.to(dtype)
    elif qtype in dequantize_functions:
        dequant_dtype = dtype if dequant_dtype == 'target' else dequant_dtype
        return dequantize(tensor.data, qtype, oshape, dtype=dequant_dtype).to(
            dtype)
    else:
        tqdm.write(f'Processing tensor: qtype: {qtype}, {oshape}')
        new = gq(tensor.cpu().numpy(), qtype)
        return torch.from_numpy(new).to(tensor.device, dtype=dtype)
def dequantize_blocks_BF16(blocks, block_size, type_size, dtype=None):
    return (blocks.view(torch.int16).to(torch.int32) << 16).view(torch.float32)
def dequantize_blocks_Q8_0(blocks, block_size, type_size, dtype=None):
    d = blocks[:, :2].view(torch.float16).to(dtype)
    x = blocks[:, 2:].view(torch.int8)
    return x * d
def dequantize_blocks_Q4_0(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    d = blocks[:, :2].view(torch.float16).to(dtype)
    qs = blocks[:, 2:]
    qs = qs.reshape((n_blocks, -1, 1, block_size // 2)) >> torch.tensor([0,
        4], device=d.device, dtype=torch.uint8).reshape((1, 1, 2, 1))
    qs = (qs & 15).reshape((n_blocks, -1)).to(torch.int8) - 8
    return d * qs
def dequantize_blocks_Q4_1(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    d = blocks[:, :2].view(torch.float16).to(dtype)
    m = blocks[:, 2:4].view(torch.float16).to(dtype)
    qs = blocks[:, 4:]
    qs = qs.reshape((n_blocks, -1, 1, block_size // 2)) >> torch.tensor([0,
        4], device=d.device, dtype=torch.uint8).reshape(1, 1, 2, 1)
    qs = (qs & 15).reshape(n_blocks, -1)
    return d * qs + m
from .quant5b import to_uint32
def dequantize_blocks_Q5_0(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    d = blocks[:, :2].view(torch.float16).to(dtype)
    qh = blocks[:, 2:6]
    qs = blocks[:, 6:]
    qh = to_uint32(qh)
    qh = qh.reshape(n_blocks, 1) >> torch.arange(32, device=d.device, dtype
        =torch.int32).reshape(1, 32)
    ql = qs.reshape(n_blocks, -1, 1, block_size // 2) >> torch.tensor([0, 4
        ], device=d.device, dtype=torch.uint8).reshape(1, 1, 2, 1)
    qh = (qh & 1).to(torch.uint8)
    ql = (ql & 15).reshape(n_blocks, -1)
    qs = (ql | qh << 4).to(torch.int8) - 16
    return d * qs
def dequantize_blocks_Q5_1(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    d = blocks[:, :2].view(torch.float16).to(dtype)
    m = blocks[:, 2:4].view(torch.float16).to(dtype)
    qh = blocks[:, 4:8]
    qs = blocks[:, 8:]
    qh = to_uint32(qh)
    qh = qh.reshape((n_blocks, 1)) >> torch.arange(32, device=d.device,
        dtype=torch.int32).reshape(1, 32)
    ql = qs.reshape((n_blocks, -1, 1, block_size // 2)) >> torch.tensor([0,
        4], device=d.device, dtype=torch.uint8).reshape(1, 1, 2, 1)
    qh = (qh & 1).to(torch.uint8)
    ql = (ql & 15).reshape((n_blocks, -1))
    qs = ql | qh << 4
    return d * qs + m
QK_K = 256
from .quant5b import split_block_dims
def dequantize_blocks_Q6_K(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    ql, qh, scales, d = split_block_dims(blocks, QK_K // 2, QK_K // 4, QK_K //
        16)
    scales = scales.view(torch.int8).to(dtype)
    d = d.view(torch.float16).to(dtype)
    d = (d * scales).reshape((n_blocks, QK_K // 16, 1))
    ql = ql.reshape((n_blocks, -1, 1, 64)) >> torch.tensor([0, 4], device=d
        .device, dtype=torch.uint8).reshape((1, 1, 2, 1))
    ql = (ql & 15).reshape((n_blocks, -1, 32))
    qh = qh.reshape((n_blocks, -1, 1, 32)) >> torch.tensor([0, 2, 4, 6],
        device=d.device, dtype=torch.uint8).reshape((1, 1, 4, 1))
    qh = (qh & 3).reshape((n_blocks, -1, 32))
    q = (ql | qh << 4).to(torch.int8) - 32
    q = q.reshape((n_blocks, QK_K // 16, -1))
    return (d * q).reshape((n_blocks, QK_K))
def dequantize_blocks_Q3_K(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    hmask, qs, scales, d = split_block_dims(blocks, QK_K // 8, QK_K // 4, 12)
    d = d.view(torch.float16).to(dtype)
    lscales, hscales = scales[:, :8], scales[:, 8:]
    lscales = lscales.reshape((n_blocks, 1, 8)) >> torch.tensor([0, 4],
        device=d.device, dtype=torch.uint8).reshape((1, 2, 1))
    lscales = lscales.reshape((n_blocks, 16))
    hscales = hscales.reshape((n_blocks, 1, 4)) >> torch.tensor([0, 2, 4, 6
        ], device=d.device, dtype=torch.uint8).reshape((1, 4, 1))
    hscales = hscales.reshape((n_blocks, 16))
    scales = lscales & 15 | (hscales & 3) << 4
    scales = scales.to(torch.int8) - 32
    dl = (d * scales).reshape((n_blocks, 16, 1))
    ql = qs.reshape((n_blocks, -1, 1, 32)) >> torch.tensor([0, 2, 4, 6],
        device=d.device, dtype=torch.uint8).reshape((1, 1, 4, 1))
    qh = hmask.reshape(n_blocks, -1, 1, 32) >> torch.tensor([i for i in
        range(8)], device=d.device, dtype=torch.uint8).reshape((1, 1, 8, 1))
    ql = ql.reshape((n_blocks, 16, QK_K // 16)) & 3
    qh = qh.reshape((n_blocks, 16, QK_K // 16)) & 1 ^ 1
    q = ql.to(torch.int8) - (qh << 2).to(torch.int8)
    return (dl * q).reshape((n_blocks, QK_K))
def dequantize_blocks_Q2_K(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    scales, qs, d, dmin = split_block_dims(blocks, QK_K // 16, QK_K // 4, 2)
    d = d.view(torch.float16).to(dtype)
    dmin = dmin.view(torch.float16).to(dtype)
    dl = (d * (scales & 15)).reshape((n_blocks, QK_K // 16, 1))
    ml = (dmin * (scales >> 4)).reshape((n_blocks, QK_K // 16, 1))
    shift = torch.tensor([0, 2, 4, 6], device=d.device, dtype=torch.uint8
        ).reshape((1, 1, 4, 1))
    qs = qs.reshape((n_blocks, -1, 1, 32)) >> shift & 3
    qs = qs.reshape((n_blocks, QK_K // 16, 16))
    qs = dl * qs - ml
    return qs.reshape((n_blocks, -1))
K_SCALE_SIZE = 12
from .quant5b import get_scale_min
def dequantize_blocks_Q5_K(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    d, dmin, scales, qh, qs = split_block_dims(blocks, 2, 2, K_SCALE_SIZE, 
        QK_K // 8)
    d = d.view(torch.float16).to(dtype)
    dmin = dmin.view(torch.float16).to(dtype)
    sc, m = get_scale_min(scales)
    d = (d * sc).reshape((n_blocks, -1, 1))
    dm = (dmin * m).reshape((n_blocks, -1, 1))
    ql = qs.reshape((n_blocks, -1, 1, 32)) >> torch.tensor([0, 4], device=d
        .device, dtype=torch.uint8).reshape((1, 1, 2, 1))
    qh = qh.reshape((n_blocks, -1, 1, 32)) >> torch.tensor([i for i in
        range(8)], device=d.device, dtype=torch.uint8).reshape((1, 1, 8, 1))
    ql = (ql & 15).reshape((n_blocks, -1, 32))
    qh = (qh & 1).reshape((n_blocks, -1, 32))
    q = ql | qh << 4
    return (d * q - dm).reshape((n_blocks, QK_K))
def dequantize_blocks_Q4_K(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    d, dmin, scales, qs = split_block_dims(blocks, 2, 2, K_SCALE_SIZE)
    d = d.view(torch.float16).to(dtype)
    dmin = dmin.view(torch.float16).to(dtype)
    sc, m = get_scale_min(scales)
    d = (d * sc).reshape((n_blocks, -1, 1))
    dm = (dmin * m).reshape((n_blocks, -1, 1))
    qs = qs.reshape((n_blocks, -1, 1, 32)) >> torch.tensor([0, 4], device=d
        .device, dtype=torch.uint8).reshape((1, 1, 2, 1))
    qs = (qs & 15).reshape((n_blocks, -1, 32))
    return (d * qs - dm).reshape((n_blocks, QK_K))
def dequantize_blocks_TQ2_0(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    qs, d = split_block_dims(blocks, QK_K // 4)
    d = d.view(torch.float16).to(dtype)
    qs = qs.reshape((n_blocks, -1, 1, 32)) >> torch.tensor([0, 2, 4, 6],
        device=d.device, dtype=torch.uint8).reshape((1, 1, 4, 1))
    qs = (qs & 3).reshape((n_blocks, -1)) - 1
    return d * qs
def dequantize_blocks_TQ1_0(blocks, block_size, type_size, dtype=None):
    n_blocks = blocks.shape[0]
    qs, qh, d = split_block_dims(blocks, (QK_K - 4 * QK_K // 64) // 5, QK_K //
        64)
    d = d.view(torch.float16).to(dtype)
    qs0, qs1 = qs[..., :32], qs[..., 32:]
    qs0 = qs0.reshape((n_blocks, -1, 1, 32)) * torch.tensor([1, 3, 9, 27, 
        81], device=d.device, dtype=torch.uint8).reshape((1, 1, 5, 1))
    qs0 = qs0.reshape((n_blocks, -1))
    qs1 = qs1.reshape((n_blocks, -1, 1, 16)) * torch.tensor([1, 3, 9, 27, 
        81], device=d.device, dtype=torch.uint8).reshape((1, 1, 5, 1))
    qs1 = qs1.reshape((n_blocks, -1))
    qh = qh.reshape((n_blocks, -1, 1, 4)) * torch.tensor([1, 3, 9, 27],
        device=d.device, dtype=torch.uint8).reshape((1, 1, 4, 1))
    qh = qh.reshape((n_blocks, -1))
    qs = torch.cat([qs0, qs1, qh], dim=-1)
    qs = (qs * 3 >> 8) - 1
    return d * qs
from .quant5b import _to_uint16, _to_uint32
IQ2_KSIGNS = (
    b'\x00\x81\x82\x03\x84\x05\x06\x87\x88\t\n\x8b\x0c\x8d\x8e\x0f\x90\x11\x12\x93\x14\x95\x96\x17\x18\x99\x9a\x1b\x9c\x1d\x1e\x9f\xa0!"\xa3$\xa5\xa6\'(\xa9\xaa+\xac-.\xaf0\xb1\xb23\xb456\xb7\xb89:\xbb<\xbd\xbe?\xc0AB\xc3D\xc5\xc6GH\xc9\xcaK\xccMN\xcfP\xd1\xd2S\xd4UV\xd7\xd8YZ\xdb\\\xdd\xde_`\xe1\xe2c\xe4ef\xe7\xe8ij\xebl\xed\xeeo\xf0qr\xf3t\xf5\xf6wx\xf9\xfa{\xfc}~\xff'
    )
IQ2_GRID_MAP = 8, 25, 43
IQ2_XXS_GRID_SHAPE = 256, 8
IQ2_XXS_GRID_HEX = (
    b''
    )
IQ2_XS_GRID_SHAPE = 512, 8
IQ2_XS_GRID_HEX = (
    b''
    )
IQ2_S_GRID_SHAPE = 1024, 8
IQ2_S_GRID_HEX = (
    b''
    )
IQ3_XXS_GRID_MAP = 4, 12, 20, 28, 36, 44, 52, 62
IQ3_XXS_GRID_SHAPE = 256, 4
IQ3_XXS_GRID_HEX = (
    b''
    )
IQ3_S_GRID_MAP = 1, 3, 5, 7, 9, 11, 13, 15
IQ3_S_GRID_SHAPE = 512, 4
IQ3_S_GRID_HEX = (
    b''
    )
IQ1_GRID_MAP = -1, 0, 1
IQ1_S_GRID_SHAPE = 2048, 8
IQ1_DELTA = 0.125
IQ1_S_GRID_HEX = (
    b''
    )
from .quant5b import _build_grid
_IQ2_CONST_CACHE = {}
def _iq_consts(kind, device):
    key = kind, str(device)
    c = _IQ2_CONST_CACHE.get(key)
    if c is None:
        if kind == 'iq2_xxs':
            grid = _build_grid(IQ2_XXS_GRID_HEX, IQ2_XXS_GRID_SHAPE,
                IQ2_GRID_MAP)
        elif kind == 'iq2_xs':
            grid = _build_grid(IQ2_XS_GRID_HEX, IQ2_XS_GRID_SHAPE, IQ2_GRID_MAP
                )
        elif kind == 'iq2_s':
            grid = _build_grid(IQ2_S_GRID_HEX, IQ2_S_GRID_SHAPE, IQ2_GRID_MAP)
        elif kind == 'iq3_xxs':
            grid = _build_grid(IQ3_XXS_GRID_HEX, IQ3_XXS_GRID_SHAPE,
                IQ3_XXS_GRID_MAP)
        elif kind == 'iq3_s':
            grid = _build_grid(IQ3_S_GRID_HEX, IQ3_S_GRID_SHAPE, IQ3_S_GRID_MAP
                )
        elif kind in ('iq1_s', 'iq1_m'):
            grid = _build_grid(IQ1_S_GRID_HEX, IQ1_S_GRID_SHAPE, IQ1_GRID_MAP)
        else:
            raise ValueError(kind)
        c = {'grid': grid.to(device), 'ksigns': torch.tensor(list(
            IQ2_KSIGNS), dtype=torch.int64, device=device), 'bits': torch.
            arange(8, dtype=torch.int64, device=device), 'sh_0_7_14_21':
            torch.tensor([0, 7, 14, 21], dtype=torch.int64, device=device),
            'sh_0_8_16_24': torch.tensor([0, 8, 16, 24], dtype=torch.int64,
            device=device), 'sh_0_4': torch.tensor([0, 4], dtype=torch.
            int64, device=device), 'sh_0_2_4_6': torch.tensor([0, 2, 4, 6],
            dtype=torch.int64, device=device), 'sh_0_3_6_9': torch.tensor([
            0, 3, 6, 9], dtype=torch.int64, device=device), 'sh_12_8_4_0':
            torch.tensor([12, 8, 4, 0], dtype=torch.int64, device=device)}
        _IQ2_CONST_CACHE[key] = c
    return c
def _signs_from_bytes(sign_bytes, bits):
    s = sign_bytes.unsqueeze(-1) >> bits & 1
    return 1.0 - 2.0 * s.to(torch.float32)
def dequantize_blocks_IQ2_XXS(blocks, block_size=QK_K, type_size=None,
    dtype=None):
    n_blocks = blocks.shape[0]
    c = _iq_consts('iq2_xxs', blocks.device)
    d, qs = split_block_dims(blocks, 2)
    d = d.contiguous().view(torch.float16).to(torch.float32)
    qs = _to_uint32(qs.reshape(n_blocks, -1, 2, 4))
    db = d * (0.5 + (qs[..., 1] >> 28).to(torch.float32)) * 0.25
    db = db.reshape(n_blocks, -1, 1, 1)
    sidx = qs[..., 1].unsqueeze(-1) >> c['sh_0_7_14_21'] & 127
    signs = _signs_from_bytes(c['ksigns'][sidx], c['bits'])
    gidx = qs[..., 0].unsqueeze(-1) >> c['sh_0_8_16_24'] & 255
    grid = c['grid'][gidx]
    out = (db * grid * signs).reshape(n_blocks, -1)
    if dtype is not None:
        out = out.to(dtype)
    return out
def dequantize_blocks_IQ2_XS(blocks, block_size=QK_K, type_size=None, dtype
    =None):
    n_blocks = blocks.shape[0]
    c = _iq_consts('iq2_xs', blocks.device)
    d, qs, scales = split_block_dims(blocks, 2, 2 * QK_K // 8)
    d = d.contiguous().view(torch.float16).to(torch.float32)
    qs = _to_uint16(qs.reshape(n_blocks, -1, 2))
    scales = scales.to(torch.int64).unsqueeze(-1) >> c['sh_0_4'] & 15
    scales = scales.reshape(n_blocks, -1).to(torch.float32)
    db = (d * (0.5 + scales) * 0.25).reshape(n_blocks, -1, 1, 1)
    signs = _signs_from_bytes(c['ksigns'][qs >> 9], c['bits'])
    signs = signs.reshape(n_blocks, -1, 2, 8)
    grid = c['grid'][qs & 511].reshape(n_blocks, -1, 2, 8)
    out = (db * grid * signs).reshape(n_blocks, -1)
    if dtype is not None:
        out = out.to(dtype)
    return out
def dequantize_blocks_IQ2_S(blocks, block_size=QK_K, type_size=None, dtype=None
    ):
    n_blocks = blocks.shape[0]
    c = _iq_consts('iq2_s', blocks.device)
    d, qs, signs, qh, scales = split_block_dims(blocks, 2, QK_K // 8, QK_K //
        8, QK_K // 32)
    d = d.contiguous().view(torch.float16).to(torch.float32)
    scales = scales.to(torch.int64).unsqueeze(-1) >> c['sh_0_4'] & 15
    scales = scales.reshape(n_blocks, -1).to(torch.float32)
    db = (d * (0.5 + scales) * 0.25).reshape(n_blocks, -1, 1, 1)
    signs = _signs_from_bytes(signs.to(torch.int64), c['bits'])
    signs = signs.reshape(n_blocks, -1, 2, 8)
    qh = qh.to(torch.int64).unsqueeze(-1) >> c['sh_0_2_4_6'] & 3
    gidx = qs.to(torch.int64) | qh.reshape(n_blocks, -1) << 8
    grid = c['grid'][gidx].reshape(n_blocks, -1, 2, 8)
    out = (db * grid * signs).reshape(n_blocks, -1)
    if dtype is not None:
        out = out.to(dtype)
    return out
def dequantize_blocks_IQ3_XXS(blocks, block_size=QK_K, type_size=None,
    dtype=None):
    n_blocks = blocks.shape[0]
    c = _iq_consts('iq3_xxs', blocks.device)
    d, rest = split_block_dims(blocks, 2)
    qs, scales = split_block_dims(rest, QK_K // 4)
    d = d.contiguous().view(torch.float16).to(torch.float32)
    qs = qs.contiguous().to(torch.int64)
    scales = _to_uint32(scales.reshape(n_blocks, -1, 4))
    db = d * (0.5 + (scales >> 28).to(torch.float32)) * 0.5
    db = db.reshape(n_blocks, -1, 1, 1)
    sidx = scales.unsqueeze(-1) >> c['sh_0_7_14_21'] & 127
    signs = _signs_from_bytes(c['ksigns'][sidx], c['bits'])
    grid = c['grid'][qs].reshape(n_blocks, -1, 4, 8)
    out = (db * grid * signs).reshape(n_blocks, -1)
    if dtype is not None:
        out = out.to(dtype)
    return out
def dequantize_blocks_IQ3_S(blocks, block_size=QK_K, type_size=None, dtype=None
    ):
    n_blocks = blocks.shape[0]
    c = _iq_consts('iq3_s', blocks.device)
    d, rest = split_block_dims(blocks, 2)
    qs, rest = split_block_dims(rest, QK_K // 4)
    qh, rest = split_block_dims(rest, QK_K // 32)
    signs, scales = split_block_dims(rest, QK_K // 8)
    d = d.contiguous().view(torch.float16).to(torch.float32)
    scales = scales.contiguous().to(torch.int64)
    scales = scales.unsqueeze(-1) >> c['sh_0_4'] & 15
    db = d * (1 + 2 * scales.reshape(n_blocks, -1).to(torch.float32))
    db = db.reshape(n_blocks, -1, 1, 1)
    signs = _signs_from_bytes(signs.contiguous().to(torch.int64), c['bits'])
    signs = signs.reshape(n_blocks, -1, 4, 8)
    qh = qh.contiguous().to(torch.int64).unsqueeze(-1) >> c['bits'] & 1
    qs = qs.contiguous().to(torch.int64) | qh.reshape(n_blocks, -1) << 8
    grid = c['grid'][qs].reshape(n_blocks, -1, 4, 8)
    out = (db * grid * signs).reshape(n_blocks, -1)
    if dtype is not None:
        out = out.to(dtype)
    return out
def dequantize_blocks_IQ1_S(blocks, block_size=QK_K, type_size=None, dtype=None
    ):
    n_blocks = blocks.shape[0]
    c = _iq_consts('iq1_s', blocks.device)
    d, qs, qh = split_block_dims(blocks, 2, QK_K // 8)
    d = d.contiguous().view(torch.float16).to(torch.float32)
    qh = _to_uint16(qh.reshape(n_blocks, -1, 2))
    dl = d * (2 * (qh >> 12 & 7) + 1).to(torch.float32)
    dl = dl.reshape(n_blocks, -1, 1, 1)
    delta = torch.where(qh & 32768 == 0, IQ1_DELTA, -IQ1_DELTA)
    delta = delta.reshape(n_blocks, -1, 1, 1)
    hidx = qh.unsqueeze(-1) >> c['sh_0_3_6_9'] & 7
    qsi = qs.to(torch.int64) | (hidx << 8).reshape(n_blocks, -1)
    grid = c['grid'][qsi].reshape(n_blocks, -1, 4, 8)
    out = (dl * (grid + delta)).reshape(n_blocks, -1)
    if dtype is not None:
        out = out.to(dtype)
    return out
def dequantize_blocks_IQ1_M(blocks, block_size=QK_K, type_size=None, dtype=None
    ):
    n_blocks = blocks.shape[0]
    c = _iq_consts('iq1_m', blocks.device)
    qs, qh, scales = split_block_dims(blocks, QK_K // 8, QK_K // 16)
    sc = _to_uint16(scales.reshape(n_blocks, -1, 2))
    d = (sc & 61440) >> c['sh_12_8_4_0']
    d = d[..., 0] | d[..., 1] | d[..., 2] | d[..., 3]
    d = d.to(torch.int16).contiguous().view(torch.float16)
    d = d.to(torch.float32).reshape(n_blocks, 1)
    scl = sc.unsqueeze(-1) >> c['sh_0_3_6_9'] & 7
    dl = d * (2 * scl.reshape(n_blocks, -1) + 1).to(torch.float32)
    dl = dl.reshape(n_blocks, -1, 2, 1, 1)
    h = qh.to(torch.int64).unsqueeze(-1) >> c['sh_0_4']
    qsi = qs.to(torch.int64) | ((h & 7) << 8).reshape(n_blocks, -1)
    delta = torch.where(h & 8 == 0, IQ1_DELTA, -IQ1_DELTA)
    delta = delta.reshape(n_blocks, -1, 2, 2, 1)
    grid = c['grid'][qsi].reshape(n_blocks, -1, 2, 2, 8)
    out = (dl * (grid + delta)).reshape(n_blocks, -1)
    if dtype is not None:
        out = out.to(dtype)
    return out
def dequantize_blocks_IQ4_NL(blocks, block_size, type_size, dtype=None):
    kvalues = torch.tensor([-127, -104, -83, -65, -49, -35, -22, -10, 1, 13,
        25, 38, 53, 69, 89, 113], dtype=torch.float32, device=blocks.device)
    n_blocks = blocks.shape[0]
    d, qs = split_block_dims(blocks, 2)
    d = d.view(torch.float16).to(dtype)
    qs = qs.reshape((n_blocks, -1, 1, block_size // 2)) >> torch.tensor([0,
        4], device=blocks.device, dtype=torch.uint8).reshape((1, 1, 2, 1))
    qs = (qs & 15).reshape((n_blocks, -1)).to(torch.int64)
    kvalues = kvalues.view(1, 1, 16)
    qs = qs.unsqueeze(-1)
    qs = torch.gather(kvalues.expand(qs.shape[0], qs.shape[1], 16), 2, qs)
    qs = qs.squeeze(-1).to(dtype)
    return d * qs
def dequantize_blocks_IQ4_XS(blocks, block_size, type_size, dtype=None):
    kvalues = torch.tensor([-127, -104, -83, -65, -49, -35, -22, -10, 1, 13,
        25, 38, 53, 69, 89, 113], dtype=torch.float32, device=blocks.device)
    n_blocks = blocks.shape[0]
    d, scales_h, scales_l, qs = split_block_dims(blocks, 2, 2, QK_K // 64)
    d = d.view(torch.float16).to(dtype)
    scales_h = scales_h.view(torch.int16)
    scales_l = scales_l.reshape((n_blocks, -1, 1)) >> torch.tensor([0, 4],
        device=blocks.device, dtype=torch.uint8).reshape((1, 1, 2))
    scales_h = scales_h.reshape((n_blocks, 1, -1)) >> torch.tensor([(2 * i) for
        i in range(QK_K // 32)], device=blocks.device, dtype=torch.uint8
        ).reshape((1, -1, 1))
    scales_l = scales_l.reshape((n_blocks, -1)) & 15
    scales_h = scales_h.reshape((n_blocks, -1)) & 3
    scales = (scales_l | scales_h << 4) - 32
    dl = (d * scales.to(dtype)).reshape((n_blocks, -1, 1))
    shifts_q = torch.tensor([0, 4], device=blocks.device, dtype=torch.uint8
        ).reshape(1, 1, 2, 1)
    qs = qs.reshape((n_blocks, -1, 1, 16)) >> shifts_q
    qs = (qs & 15).reshape((n_blocks, -1, 32)).to(torch.int64)
    kvalues = kvalues.view(1, 1, 1, 16)
    qs = qs.unsqueeze(-1)
    qs = torch.gather(kvalues.expand(qs.shape[0], qs.shape[1], qs.shape[2],
        16), 3, qs)
    qs = qs.squeeze(-1).to(dtype)
    return (dl * qs).reshape(n_blocks, -1)
from .quant5b import e8m0_to_fp32_half
def dequantize_blocks_MXFP4(blocks, block_size, type_size=None, dtype=None):
    kvalues = torch.tensor([0, 1, 2, 3, 4, 6, 8, 12, 0, -1, -2, -3, -4, -6,
        -8, -12], dtype=torch.float32, device=blocks.device).view(1, 1, 16)
    n_blocks = blocks.shape[0]
    e, qs = split_block_dims(blocks, 1)
    d = e8m0_to_fp32_half(e)
    qs = qs.reshape(n_blocks, 1, block_size // 2)
    shifts = torch.tensor([0, 4], dtype=qs.dtype, device=blocks.device
        ).reshape(1, 2, 1)
    qs = qs >> shifts & 15
    qs = qs.to(torch.long)
    qs = torch.gather(kvalues.expand(n_blocks, 2, 16), dim=2, index=qs)
    qs = qs.reshape(n_blocks, block_size)
    out = d * qs
    if dtype is not None:
        out = out.to(dtype)
    return out
from .quant5b import ue4m3_to_fp32
def dequantize_blocks_NVFP4(blocks, block_size, type_size=None, dtype=None):
    kvalues = torch.tensor([0, 1, 2, 3, 4, 6, 8, 12, 0, -1, -2, -3, -4, -6,
        -8, -12], dtype=torch.float32, device=blocks.device).view(1, 1, 16)
    n_super = blocks.shape[0]
    d_bytes, qs = split_block_dims(blocks, 4)
    d = ue4m3_to_fp32(d_bytes).reshape(n_super, 4, 1)
    qs = qs.reshape(n_super, 4, 8)
    lo = qs & 15
    hi = qs >> 4
    vals = torch.cat([lo, hi], dim=-1).to(torch.long)
    vals = torch.gather(kvalues.expand(n_super, 4, 16), dim=2, index=vals)
    out = (d * vals).reshape(n_super, 64)
    if dtype is not None:
        out = out.to(dtype)
    return out
